current_method = None
seen_return = {}
seen_usage = {}

all_elements = list(doc._body._body)

for i, element in enumerate(all_elements):
    if element.tag.endswith('p'):
        p = docx.text.paragraph.Paragraph(element, doc._body)
        text = p.text.strip()
        
        for key in data.keys():
            if text.startswith(key):
                if key == "12. face_recog_single" and "face_liveness" in text: continue
                if key == "15. face_ver_config_score" and "face_ver2" in text: continue
                if key == "12. face_liveness" and "info_face_liveness" in text: continue
                current_method = key
                print('Entered', current_method)
                break
                
        if not current_method:
            continue
            
        if "?????????????" in text or "???????????????" in text:
            if current_method in seen_return: continue
            seen_return[current_method] = True
            print('Modifying Return for', current_method)
            
            p.text = "????????????????"
            if p.runs: p.runs[0].bold = True
            
            # Find next table
            idx = i + 1
            while idx < len(all_elements) and not all_elements[idx].tag.endswith('tbl'):
                idx += 1
            if idx < len(all_elements):
                t = docx.table.Table(all_elements[idx], doc._body)
                try: t.rows[0].cells[0].text = data[current_method]["return_val"]
                except: pass
                
        if "?????????????????" in text:
            if current_method in seen_usage: continue
            seen_usage[current_method] = True
            print('Modifying Usage for', current_method)
            
            # Find next table
            idx = i + 1
            while idx < len(all_elements) and not all_elements[idx].tag.endswith('tbl'):
                idx += 1
            if idx < len(all_elements):
                t = docx.table.Table(all_elements[idx], doc._body)
                try: t.rows[0].cells[0].text = data[current_method]["usage"]
                except: pass
                
                # Clone for response
                new_p_elem = copy.deepcopy(element)
                new_t_elem = copy.deepcopy(all_elements[idx])
                
                new_p = docx.text.paragraph.Paragraph(new_p_elem, doc._body)
                new_p.text = "???????? response (HTTP 200)"
                if new_p.runs: new_p.runs[0].bold = True
                
                new_t = docx.table.Table(new_t_elem, doc._body)
                try: new_t.rows[0].cells[0].text = data[current_method]["response"]
                except: pass
                
                all_elements[idx].addnext(new_p_elem)
                new_p_elem.addnext(new_t_elem)

doc.save('api_documentation_v2 (1).docx')
